const drawing = async(webGPU) => {
    const triangleMesh: TriangleMesh = new TriangleMesh(webGPU.device);

    const bindGroupLayout = webGPU.device.createBindGroupLayout({
        entries: [],
    });

    const bindGroup = webGPU.device.createBindGroup({
        layout: bindGroupLayout,
        entries: []
    });
    
    const pipelineLayout = webGPU.device.createPipelineLayout({
        bindGroupLayouts: [bindGroupLayout]
    });

    const pipeline = webGPU.device.createRenderPipeline({
        vertex : {
            module : webGPU.device.createShaderModule({
                code : shader
            }),
            entryPoint : 'vs_main',
            buffers: [triangleMesh.bufferLayout,]
        },

        fragment : {
            module : webGPU.device.createShaderModule({
                code : shader
            }),
            entryPoint : 'fs_main',
            targets : [{
                format : webGPU.format
            }]
        },

        primitive : {
            topology : 'triangle-list'
        },

        layout: pipelineLayout
    });

    //command encoder: records draw commands for submission
    const commandEncoder : GPUCommandEncoder = webGPU.device.createCommandEncoder();
    //texture view: image view to the color buffer in this case
    const textureView : GPUTextureView = webGPU.context.getCurrentTexture().createView();
    //renderpass: holds draw commands, allocated from command encoder
    const renderpass : GPURenderPassEncoder = commandEncoder.beginRenderPass({
        //@ts-ignore
        colorAttachments: [{
            view: textureView,
            clearValue: {r: 0.0, g: 0.0, b: 0.0, a: 1.0},
            loadOp: 'clear',
            storeOp: 'store'
        }]
    });
    renderpass.setPipeline(pipeline);
    renderpass.setVertexBuffer(0, triangleMesh.buffer);
    renderpass.setBindGroup(0, bindGroup)
    renderpass.draw(3, 1, 0, 0);
    renderpass.end();

    webGPU.device.queue.submit([commandEncoder.finish()]);
}

